#!/usr/bin/env python3
# 覆盖率检查 + 补漏文件生成
# 用法：python3 coverage.py 01 02 ...   （只统计）
#       python3 coverage.py --gaps 01 02 ...   （同时生成 s1/gaps/NN.md）
import re
import sys
from pathlib import Path

S1 = Path('/Users/kk/.kiro/crew/scratch/runtime-7213e8c2/s1')
TRIVIAL = [
    re.compile(r'^(继续|好的?|行|可以|ok|嗯|对|是的|开始|下一个|收到)[。！!，,\s]*$', re.I),
    re.compile(r'^(直接)?(输出|出|给我|再出|重出)?\s*(gen|GEN)[-\s]?[a-zA-Z0-9]{1,5}[\s,，、]*((gen|GEN)[-\s]?[a-zA-Z0-9]{1,5}[\s,，、]*)*(的)?(终稿|提示词|底稿)?[。！!]?$', re.I),
    re.compile(r'^(直接)?(继续)?出\s*(GEN|gen)?-?[a-zA-Z0-9]{0,5}\s*(终稿|提示词)?$', re.I),
    re.compile(r'^把剩下的终稿给到我$'),
]
CMD_MARK = re.compile(r'(进入\s*[ASD]／|进入 [ASD]|【约束词】|# 导演共创|【读取与边界】)')
SCRIPT_LINE = re.compile(r'^\s*(△|\*\*\d+-\d+|\d+-\d+\s|人物[：:]|\*\*人物|[^\s：:]{1,6}[：:]（)')


def norm(s):
    return re.sub(r'[^\w\u4e00-\u9fff]', '', s)


def blocks(text):
    out = []
    for p in re.split(r'\n(?=【(?:你|助手|写文件) )', text):
        m = re.match(r'【(你|助手|写文件) ([^】]*)】', p)
        if not m:
            continue
        out.append((m.group(1), m.group(2), p[m.end():].strip()))
    return out


def substantive(body):
    s = body.split('……[中间省略')[0]
    s = re.sub(r'!\[[^\]]*\]\([^)]*\)', '', s)
    m = CMD_MARK.search(s)
    if m:
        s = s[:m.start()]
    keep = []
    for line in s.split('\n'):
        if SCRIPT_LINE.match(line):
            break
        keep.append(line)
    s = '\n'.join(keep).strip()
    if len(norm(s)) < 6:
        return ''
    if any(t.match(s) for t in TRIVIAL):
        return ''
    return s


def main(args):
    make_gaps = '--gaps' in args
    nums = [a for a in args if not a.startswith('--')]
    (S1 / 'gaps').mkdir(exist_ok=True)
    grand_total = grand_missed = 0
    for n in nums:
        chunk = next((S1 / 'chunks').glob(f'{n}_*.md'))
        mined_p = S1 / 'mined' / f'{n}.md'
        if not mined_p.exists():
            print(f'== {n}: 没有 mined 文件')
            continue
        mined = norm(mined_p.read_text(encoding='utf-8'))
        bl = blocks(chunk.read_text(encoding='utf-8'))
        total, missed = 0, []
        for i, (kind, ts, body) in enumerate(bl):
            if kind != '你':
                continue
            s = substantive(body)
            if not s:
                continue
            total += 1
            ns = norm(s)
            win = 8 if len(ns) < 30 else 12
            hit = any(ns[j:j + win] in mined for j in range(0, max(1, len(ns) - win + 1), 2))
            if hit:
                continue
            prev_writes, prev_asst, next_asst = [], '', ''
            for k in range(i - 1, -1, -1):
                if bl[k][0] == '你':
                    break
                if bl[k][0] == '写文件' and len(prev_writes) < 4:
                    prev_writes.append(f'【写文件 {bl[k][1]}】{bl[k][2]}')
                if bl[k][0] == '助手' and not prev_asst:
                    prev_asst = f'【助手 {bl[k][1]}】（前一条回复的结尾）{bl[k][2][-350:]}'
            for k in range(i + 1, len(bl)):
                if bl[k][0] == '你':
                    break
                if bl[k][0] == '助手':
                    next_asst = f'【助手 {bl[k][1]}】（后一条回复的开头）{bl[k][2][:350]}'
                    break
            missed.append((ts, s, list(reversed(prev_writes)), prev_asst, next_asst))
        grand_total += total
        grand_missed += len(missed)
        print(f'== {n}: 有内容的用户消息 {total} 条，已摘录 {total - len(missed)} 条，漏 {len(missed)} 条')
        if make_gaps and missed:
            out = [f'# 补漏：{chunk.name} 里上一轮没抽到的用户消息（共 {len(missed)} 条）\n',
                   '每条前后附了上下文，用来判断说的是哪个文件、哪一版。\n']
            for k, (ts, s, pw, pa, na) in enumerate(missed, 1):
                out.append(f'\n### 漏抄 {k}\n')
                out.extend(w + '\n' for w in pw)
                if pa:
                    out.append(pa + '\n')
                out.append(f'【你 {ts}】\n{s}\n')
                if na:
                    out.append(na + '\n')
            (S1 / 'gaps' / f'{n}.md').write_text(''.join(out), encoding='utf-8')
    print(f'== 合计：有内容 {grand_total} 条，漏 {grand_missed} 条')


if __name__ == '__main__':
    main(sys.argv[1:])

