"""终稿检查 v4（由 31_D2终稿检查.sh 扩展）

用法：python3 04a_终稿检查.py <终稿.md>

查这些（都是第一季成片或平台拦截证实过的毛病，编号对应 01_视频模型病历.md）：
- 代码块字数（硬上限 1 万，M33）
- 三个一级板块、约束词 12 区块、每个 CUT 16 项标签和静止观察四行
- 首句三道锁：禁文字水印、反 2D 锁（M01）、肤色锁（M02）
- 审核高危词（M28-M31）、比喻和颜色词（M02、M31）、拖字语速词（M21）
- 空景写法（M06）、门纸剪影倒影（M36）、系统提示音（M20）、摄影机入画（M24）
只报问题，不改稿。
"""
import re
import sys
from pathlib import Path

LABELS = ['机位与构图', '进入状态', '触发', '动作', '六类表演', '台词', '景别与层次', '景深与焦点',
          '摄影机', '静止观察', '声音', '光线与材质', '切入理由', '切点', '可见或可听停点', '下一镜接口']
STILL4 = ['画内变化', '声音关系', '结果观察', '停点']
BLOCKS12 = ['唯一戏剧任务', '首帧', '核心动作链', '主导画面机制', '摄影总设计', '世界不变量',
            '连续表演总链', '六类表演总链', '整体声音链', '段尾状态', '下一段接口']
WATCH = {
    '审核高危词（M28-M31）': r'砸|压得|压着他|掐|踹|血|胸口|胸前起伏|瘫|插死|插进|床帐|揉胸|额头贴地|贴地叩|憋着气|蠢货|欺压|脱衣|赤裸|裸',
    '比喻和颜色词（M02、M31）': r'像|仿佛|如同|宛如|好似|犹如|恍若|似的|般地|发白|发灰|发青|死灰|铁青|面如|石化|冻住|脸色|涨红|通红|煤灰|苍白',
    '拖字语速词（M21）': r'慢悠悠|拖长|拉长|拖一点|拖一拍|顿半拍|一字一顿|放慢|慢慢地说|一个字一个字',
    '空景写法（M06）': r'空无一人|空床|空荡荡|没有人影',
    '门纸剪影倒影（M36）': r'剪影|倒影|门纸|窗纸|投影在',
}
OK_CONTEXT = r'不(要|写|出|生成|是|得|拖|许|能)|没有|无|禁|别|避免'


def code_block(text):
    m = re.search(r'```[^\n]*\n(.*?)```', text, re.S)
    return m.group(1) if m else ''


def main(path):
    p = Path(path)
    if not p.exists():
        print(f'用法: python3 {sys.argv[0]} <终稿.md>')
        return 1
    body = code_block(p.read_text(encoding='utf-8'))
    if not body:
        print('有问题：没找到代码块')
        return 1
    problems = []
    n = len(body)
    print(f'字数：{n}' + ('（超过 1 万，必须压）' if n > 10000 else ''))
    if n > 10000:
        problems.append('字数超 1 万')

    for b in ['【约束词】', '【对应图片】', '【镜头']:
        if b not in body:
            problems.append(f'缺板块 {b}')
    cons = body.split('【对应图片】')[0]
    miss = [k for k in BLOCKS12 if k not in cons]
    if miss:
        problems.append('约束词缺区块：' + '、'.join(miss))

    head = cons[:600]
    if '不要生成音乐' not in head or '字幕' not in head or '水印' not in head:
        problems.append('首句缺"不要生成音乐、字幕、水印、文字"')
    if not re.search(r'不是\s*2D|非\s*2D|不是二维', cons):
        problems.append('缺反 2D 锁（M01）')
    if '肤色' not in cons:
        problems.append('缺肤色锁（M02）')
    if '系统' in body and '不要生成系统提示音' not in body:
        problems.append('出现系统画面，但没写"不要生成系统提示音"（M20）')
    if re.search(r'环绕|绕着|绕到', body) and not re.search(r'不出现摄影机|摄影机.{0,6}不入画|不出现.{0,6}拍摄器材', body):
        problems.append('有环绕运镜，但没写"画面里不出现摄影机、拍摄器材"（M24）')

    shots = body.split('【镜头')[-1]
    heads = re.findall(r'^\s*[0-9.]+\s*[-–—]\s*[0-9.]+\s*秒\s*[｜|]', shots, re.M)
    cuts = len(heads)
    print(f'CUT 数：{cuts}')
    if cuts == 0:
        problems.append('镜头板块里没找到"起止秒｜CUT"开头的镜头')
    counts = {k: len(re.findall(rf'(^|\n)\s*(\d+\.\s*)?[-•]?\s*{k}\s*[：:]', shots)) for k in LABELS}
    counts.update({k: len(re.findall(rf'(^|\n)\s*[-•]?\s*{k}\s*[：:]', shots)) for k in STILL4})
    short = {k: v for k, v in counts.items() if v < cuts}
    print('标签计数（每项应 ≥ CUT 数）：' + '  '.join(f'{k}={v}' for k, v in counts.items()))
    if short:
        problems.append('这些标签少于 CUT 数：' + '、'.join(f'{k}({v}/{cuts})' for k, v in short.items()))

    parts = re.split(r'(?m)^\s*[0-9.]+\s*[-–—]\s*[0-9.]+\s*秒\s*[｜|]', shots)[1:]
    if parts:
        lens = [len(x) for x in parts]
        print('各 CUT 字数：' + ' '.join(map(str, lens)))
        thin = [i + 1 for i, L in enumerate(lens) if L < 250]
        if thin:
            problems.append('这些 CUT 不到 250 字：第 ' + '、'.join(map(str, thin)) + ' 个')
        if len(lens) >= 4 and sum(lens[-2:]) / 2 < 0.6 * sum(lens[:2]) / 2:
            problems.append('后面的 CUT 比前面明显短（越写越省）')

    for name, pat in WATCH.items():
        hits = []
        for m in re.finditer(pat, body):
            ctx = body[max(0, m.start() - 10): m.end() + 10].replace('\n', ' ')
            if re.search(OK_CONTEXT, body[max(0, m.start() - 8): m.start()]):
                continue
            if m.group(0) == '像' and re.search(r'(胸像|图像|影像|画像|像素|参考图像|镜像)', ctx):
                continue
            hits.append(ctx)
        if hits:
            problems.append(f'{name}：' + '｜'.join(hits[:8]) + (f' 等 {len(hits)} 处' if len(hits) > 8 else ''))

    print('---')
    if problems:
        print(f'有 {len(problems)} 个问题：')
        for i, x in enumerate(problems, 1):
            print(f'{i}. {x}')
    else:
        print('通过')
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1] if len(sys.argv) > 1 else ''))
