🔧 cd /Users/kk/.kiro/crew/scratch/runtime-7213e8c2/s1 && cat > verify_cols.py <<'EOF'
import re, sys
from pathlib import Path
S = Path('/Users/kk/.kiro/crew/scratch/runtime-7213e8c2/s1')
Q = re.compile(r'["“「『]([^"”」』]{4,200})["”」』]')
def norm(s): return re.sub(r'[\s　，。、；：！？,.;:!?（）()【】\[\]…—\-·｜|*`]', '', s)
def check(judged, d):
    files = {L: norm((d/f'{L}.md').read_text(encoding='utf-8')) for L in 'XYZPQRS' if (d/f'{L}.md').exists()}
    letters = list(files)
    hits = {a: {b: 0 for b in letters} for a in letters}
    t = (S/'judged'/judged).read_text(encoding='utf-8')
    header = None
    for line in t.splitlines():
        if not line.startswith('|'): header = None if not line.strip() else header; continue
        cells = [c.strip() for c in line.strip().strip('|').split('|')]
        if all(re.fullmatch(r':?-{2,}:?', c) or c == '' for c in cells): continue
        if header is None:
            header = cells; continue
        for h, c in zip(header, cells):
            m = re.match(r'^\**([XYZPQRS])\b', h.replace(' ', '')) or re.match(r'^\**([XYZPQRS])', h)
            if not m or m.group(1) not in hits: continue
            col = m.group(1)
            for q in Q.findall(c):
                for seg in re.split(r'……|…|\.\.\.', q):
                    seg = norm(seg)
                    if len(seg) < 6: continue
                    for L, body in files.items():
                        if seg in body: hits[col][L] += 1
    print(f'== {judged}  （行=评审写的列，列=引文实际出自哪份）')
    print('     ' + ''.join(f'{L:>5}' for L in letters))
    bad = []
