import re, sys
from pathlib import Path

E = Path(__file__).resolve().parent
Q = re.compile(r'[「"“『]([^」"”』]{4,200})[」"”』]')


def norm(s):
    return re.sub(r'[\s　，。、；：！？,.;:!?（）()【】\[\]…—\-·｜|*`＋+／/~～]', '', s)


def check(q):
    d = E / 'judge' / q
    files = {L: norm((d / f'{L}.md').read_text(encoding='utf-8')) for L in 'XY'}
    p = E / 'judged' / f'{q}.md'
    if not p.exists():
        print(f'== {q}  还没交')
